    remote=read(D/'REMOTE_TO_LOCAL_FINAL_VERIFICATION.json');local=read(D/'LOCAL_FOUNDATION_AUDIT.json');assert remote['status']=='PASS' and local['status']=='PASS' and not local['issues'];initial=read(D/'MISSING_BACKUPS_INITIAL.json');supplement=read(D/'SUPPLEMENTAL_BACKUP_VERIFICATION.json');inv=read(D/'REMOTE_RESEARCH_INVENTORY.json')
